using System;
using System.Collections.Generic;
using Nino.Core;

// Classes whose generated body is flat (#355, the generator seam: raw members, bools, raw T?s and strings, fields or
// properties, through Nino.Core's flat kernels), and twins of them that are not (a serialization callback, which no
// flat body has; the same bytes): positional, as flat bodies need.
// Generated by the Roslyn 4.3 build, as in Unity. FlatTests compares the two.
namespace Nino.UnitTests.Subset.Flat
{
    public enum FlatKind : byte { None, Small, Large }

    /// <summary>
    /// A flat class that is not sealed (#355): one string after primitives declared largest first, which CoreCLR lays
    /// out as the wire does (one block of 21 bytes); a subtype leaves the run.
    /// </summary>
    [NinoType]
    public class FlatOne
    {
        public long Stamp;
        public double Score;
        public int Id;
        public FlatKind Kind;
        public string Name;
    }

    [NinoType]
    public class FlatOneDerived : FlatOne
    {
        public int Extra;
    }

    /// <summary>
    /// A flat class that is not sealed and has no subtype: its runs are written by the typed kernels (a base with
    /// subtypes, <see cref="FlatOne"/>, writes them through its dispatch loop and reads them through the kernels).
    /// </summary>
    [NinoType]
    public class FlatLeaf
    {
        public int Id;
        public string Name;
    }

    /// <summary><see cref="FlatOne"/>'s members as auto-properties and a callback: the same body, not flat (the generated
    /// body).</summary>
    [NinoType]
    public class FlatOneProps
    {
        [NinoOnSerializing]
        internal void Writing() { }

        public long Stamp { get; set; }
        public double Score { get; set; }
        public int Id { get; set; }
        public FlatKind Kind { get; set; }
        public string Name { get; set; }
    }

    /// <summary>A sealed flat class: several strings (one UTF-8) between a primitive, a struct and a bool.</summary>
    [NinoType]
    public sealed class FlatMany
    {
        public int Id;
        public string Name;
        [NinoUtf8] public string Tag;
        public DateTime At;
        public bool Flag;
        public string Text;
        public decimal Price;
    }

    /// <summary><see cref="FlatMany"/> as auto-properties and a callback: not flat, the same bytes.</summary>
    [NinoType]
    public sealed class FlatManyProps
    {
        [NinoOnSerializing]
        internal void Writing() { }

        public int Id { get; set; }
        public string Name { get; set; }
        [NinoUtf8] public string Tag { get; set; }
        public DateTime At { get; set; }
        public bool Flag { get; set; }
        public string Text { get; set; }
        public decimal Price { get; set; }
    }

    /// <summary>A flat class holding flat classes and lists of them (members and runs through one parent).</summary>
    [NinoType]
    public sealed class FlatHolder
    {
        public FlatMany One;
        public List<FlatMany> Many;
        public FlatOne[] Ones;
    }

    /// <summary>
    /// A chain of nodes each holding a run of flat classes: past NinoDepth.Inline the runs go element by element, as
    /// deferred bodies (#355).
    /// </summary>
    [NinoType]
    public sealed class FlatNode
    {
        public FlatMany[] Items;
        public FlatNode Next;
    }

    /// <summary><see cref="FlatNode"/> over <see cref="FlatManyProps"/>: the same bytes through generated bodies.</summary>
    [NinoType]
    public sealed class FlatNodeProps
    {
        public FlatManyProps[] Items;
        public FlatNodeProps Next;
    }

    /// <summary>
    /// A sealed flat class through every member kind of step B (#355): fields and auto-properties, raw <c>T?</c>s (one
    /// a property, one a struct's), a string property and a UTF-8 field.
    /// </summary>
    [NinoType]
    public sealed class FlatSlots
    {
        public int Id;
        public int? Count { get; set; }
        public string Name { get; set; }
        public long? Big;
        public DateTime? When;
        public bool Flag { get; set; }
        public double Score { get; set; }
        [NinoUtf8] public string Tag;
        public decimal Price { get; set; }
    }

    /// <summary><see cref="FlatSlots"/> with a callback: not flat, the same bytes.</summary>
    [NinoType]
    public sealed class FlatSlotsTwin
    {
        [NinoOnSerializing]
        internal void Writing() { }

        public int Id;
        public int? Count { get; set; }
        public string Name { get; set; }
        public long? Big;
        public DateTime? When;
        public bool Flag { get; set; }
        public double Score { get; set; }
        [NinoUtf8] public string Tag;
        public decimal Price { get; set; }
    }

    /// <summary>A flat class without a string (#355 step B): raw members and raw <c>T?</c>s, not a block.</summary>
    [NinoType]
    public sealed class FlatBare
    {
        public int A;
        public short? B;
        public long C { get; set; }
        public byte? D;
    }

    /// <summary><see cref="FlatBare"/> with a callback: not flat, the same bytes.</summary>
    [NinoType]
    public sealed class FlatBareTwin
    {
        [NinoOnSerializing]
        internal void Writing() { }

        public int A;
        public short? B;
        public long C { get; set; }
        public byte? D;
    }

    /// <summary>
    /// A struct whose body is flat (#355 step B): its runs through the one item chain, each element in place, as a
    /// pair's are; one value member by member.
    /// </summary>
    [NinoType]
    public struct FlatPoint
    {
        public int Id;
        public string Name;
        public double X { get; set; }
        public bool Flag;
        public int? Count;
        public DateTime At;
        [NinoUtf8] public string Tag;
    }

    /// <summary><see cref="FlatPoint"/> with a callback: not flat, the same bytes.</summary>
    [NinoType]
    public struct FlatPointTwin
    {
        [NinoOnSerializing]
        internal void Writing() { }

        public int Id;
        public string Name;
        public double X { get; set; }
        public bool Flag;
        public int? Count;
        public DateTime At;
        [NinoUtf8] public string Tag;
    }

    /// <summary>
    /// A generic flat class whose members name no type parameter (#355 step B): its runs take the item chain where its
    /// type argument is a value type (exact code), element by element where it is a class (code shared over it).
    /// </summary>
    [NinoType]
    public sealed class FlatBox<T>
    {
        public int Id;
        public string Name;
        public long? Big { get; set; }
    }

    /// <summary><see cref="FlatBox{T}"/> with a callback: not flat, the same bytes.</summary>
    [NinoType]
    public sealed class FlatBoxTwin<T>
    {
        [NinoOnSerializing]
        internal void Writing() { }

        public int Id;
        public string Name;
        public long? Big { get; set; }
    }

    /// <summary>A generic flat struct, as <see cref="FlatBox{T}"/>.</summary>
    [NinoType]
    public struct FlatEntry<T>
    {
        public string Key;
        public int Value;
    }
}
